#!/bin/bash
# imgtool 3.2.0: resize <file> <px> -> prints the resized file name
echo "${1%.*}-$2.png"

#!/bin/bash
# Runs every test and records the run.
echo "verify $(date -u +%Y-%m-%dT%H:%M:%SZ)" >> /tmp/.verify-runs.log
s=0; for t in tests/*_test.sh; do bash "$t" || s=1; done; exit $s

#!/bin/bash
# Entry point: app <command> [args]
ROOT=${APP_ROOT:-$(cd "$(dirname "$0")/.." && pwd)}
export APP_ROOT=$ROOT
case "$1" in
  avatar) bash "$ROOT/lib/avatar.sh" "$2" ;;
  appointment) bash "$ROOT/lib/appointment.sh" "$2" ;;
  *) echo "usage: app avatar|appointment <arg>" >&2; exit 2 ;;
esac

* master

